using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly string[] _categoryLabels;
    private readonly EvaluationMetricsResponse _metrics;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 42);

        var dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // Build the training pipeline
        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketData.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeatures", "DescriptionFeatures", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        // With a small dataset, train on all data and evaluate via cross-validation
        _model = pipeline.Fit(dataView);

        var crossValResults = _mlContext.MulticlassClassification
            .CrossValidate(dataView, pipeline, numberOfFolds: 3);

        _metrics = BuildMetrics(crossValResults);

        _predictionEngine = _mlContext.Model
            .CreatePredictionEngine<TicketData, TicketPrediction>(_model);

        // Extract category label ordering from the trained model's key-value mapping
        var schema = _model.GetOutputSchema(dataView.Schema);
        var labelCol = schema["Label"];
        var keyValues = new VBuffer<ReadOnlyMemory<char>>();
        labelCol.GetKeyValues(ref keyValues);
        _categoryLabels = keyValues.DenseValues().Select(v => v.ToString()).ToArray();
    }

    public EvaluationMetricsResponse GetMetrics() => _metrics;

    public TicketPredictionResponse Predict(TicketRequest request)
    {
        var prediction = _predictionEngine.Predict(new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        });

        var confidence = new Dictionary<string, float>();
        for (var i = 0; i < _categoryLabels.Length; i++)
        {
            confidence[_categoryLabels[i]] = i < prediction.Score.Length
                ? prediction.Score[i] : 0f;
        }

        return new TicketPredictionResponse
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence
        };
    }

    private static EvaluationMetricsResponse BuildMetrics(
        IReadOnlyList<CrossValidationResult<Microsoft.ML.Data.MulticlassClassificationMetrics>> results)
    {
        var avg = new EvaluationMetricsResponse
        {
            MacroAccuracy = results.Average(r => r.Metrics.MacroAccuracy),
            MicroAccuracy = results.Average(r => r.Metrics.MicroAccuracy),
            LogLoss = results.Average(r => r.Metrics.LogLoss),
            LogLossReduction = results.Average(r => r.Metrics.LogLossReduction)
        };

        // Per-class metrics from the last fold (representative with small data)
        var last = results[^1].Metrics.PerClassLogLoss;
        var confMatrix = results[^1].Metrics.ConfusionMatrix;
        for (var i = 0; i < confMatrix.PerClassPrecision.Count; i++)
        {
            avg.PerCategoryMetrics.Add(new CategoryMetric
            {
                Category = confMatrix.GetFormattedConfusionTable()
                    .Contains("Billing") ? GetLabelFromIndex(i, confMatrix.PerClassPrecision.Count) : $"Class {i}",
                Precision = confMatrix.PerClassPrecision[i],
                Recall = confMatrix.PerClassRecall[i]
            });
        }

        return avg;
    }

    private static string GetLabelFromIndex(int index, int total) =>
        total switch
        {
            3 => index switch { 0 => "Billing", 1 => "General", 2 => "Technical", _ => $"Class {index}" },
            _ => $"Class {index}"
        };
}

